    ctx := context.WithValue(context.Background(), EdictID, edict.ID)

    // Sequential execution within a ritual
    commitHash := rg.forgeCeremony(ctx)  // Returns commit
    verdict := rg.judgeCeremony(ctx, commitHash)  // Runs tests
