// CONSTITUTIONAL PRACTICE (Li)
func (rg *RoyalGuard) enforceIsolation(parentCtx context.Context, ceremony Ceremony) context.Context {
    // Start fresh context with only EdictID (Ren), discard parent values
    base := context.WithValue(context.Background(), EdictID, parentCtx.Value(EdictID))

    // Inject only realm-specific capabilities
    return context.WithValue(base, CapsKey, ceremony.Realm.Caps())
}
```

