func (c *CourtSession) InvokeRitual(edict *Edict) tea.Cmd {
    // Audience begins - LLM goroutine spawns
    audience := &Audience{
        Minister:   RoleStrategist,
        Realm:      RealmRen,  // Cannot see Tian/Di yet
        Scrollback: make(chan Message, 100),
    }
    c.ActiveAudience = audience

    // LLM session runs in isolated goroutine
    go func() {
        ctx, cancel := context.WithTimeout(context.Background(), RitualTimeout)
        audience.CancelFunc = cancel

        // The LLM streams to the channel, not direct to TUI
        c.ministers[RoleStrategist].Execute(ctx, edict, audience.Scrollback)

        // Audience ends - seal impressed
        c.royalGuard.ImpressSeal(edict.ID, RoleStrategist)
        close(audience.Scrollback)
    }()

    // Return tea.Cmd to stream from channel to Viewport
    return c.consumeStream(audience.Scrollback)
}
```

